      SUBROUTINE REFCHKCC     FILL IN POINTERS FOR BEAM LINE SPECIFICATIONSCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM24A.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'IOUNIT.CIN'C ---------------------------------------------------------------------      CHARACTER*15    LABLE      EXTERNAL        IDATACC     PROCESS DATAC      NFAUTE = 0      NUM = 1      IOLD = 0C   70 I = ISTOR(NUM)      IF (I .LE. IOLD) GO TO 6000      TYPE = IDATA(I)      LABLE = LABEL(NUM)CC     PROCESS ORIGINAL DATAC      IF (TYPE .EQ. 24) GO TO 2400      GO TO 6000CC     DEFINED SECTIONC 2400 JDEF = IDATA(I+1)      IF (JDEF .EQ. 1 .OR. JDEF .EQ. 2) GO TO 6000      NADDEF(1) = IDATA(I+2)      NADDEF(2) = IDATA(I+3)      IF (NADDEF(1) .EQ. 0 .OR. NADDEF(2) .EQ. 0) THEN        NFAUTE = NFAUTE + 1        WRITE (NOUT,7008) LABLE 7008   FORMAT (1X,'***NO DEFINITION FOR SUBLINE ',A8)      ENDIF      GO TO 6000CC     ADVANCE TO NEXT ELEMENTC 6000 IOLD = MAX0(I,IOLD)      NUM = NUM + 1      IF (NUM .LE. NEL) GO TO 70      FLUSHL = FLUSHL .OR. NFAUTE .GT. 0      RETURN      END